stages=[
('CORPORATE STATE BEFORE 1773',['COMPANY: TRADE + TERRITORIAL POWER','NO SETTLED PARLIAMENTARY CONTROL','BENGAL CRISIS -> REGULATION'],['Company commercial rule acquired governmental functions.','Defect: private corporation exercised public power without constitutional accountability.','Consequence: Parliament intervenes, not because Company ceased to trade.'],'Corporate power first produced the need for statutory control.'),
('REGULATING ACT 1773',['GOVERNOR-GENERAL OF BENGAL','COUNCIL: 4 MEMBERS','CALCUTTA SUPREME COURT','CONTROL STILL IMPERFECT'],['Bengal presidency made supervisory centre over Bombay and Madras.','Governor-General in Council and Supreme Court created dual authorities.','Defect: jurisdictional conflict and weak central control remained.'],'1773 begins regulation, but did not create a coherent central government.'),
('SETTLEMENT ACT 1781',['COURT JURISDICTION CLARIFIED','REVENUE ACTS PROTECTED','EXECUTIVE–JUDICIARY BOUNDARY'],['Clarified Supreme Court limits over revenue administration.','Protected acts done in public/revenue capacity from ordinary court interference.','Bridge: exposed why Parliament needed a control system above ad-hoc clarification.'],'1781 repaired the 1773 court–executive conflict; it did not settle political control.'),
('PITT\'S INDIA ACT 1784',['DUAL CONTROL','BOARD OF CONTROL = GOVERNMENT','COURT OF DIRECTORS = COMMERCE'],['BOARD OF CONTROL: political, civil, military and revenue government.','COURT OF DIRECTORS: commercial administration retained.','Consequence: Company survived commercially; British Government gained decisive state supervision.'],'Pitt\'s Act separated commercial management from sovereign supervision.'),
('1786 + CHARTER ACT 1793',['1786: GOVERNOR-GENERAL POWER','1793: COMPANY MONOPOLY RENEWED','CENTRALISING TREND'],['1786 strengthened Governor-General where council opposition obstructed policy.','1793 renewed monopoly without altering dual-control principle.','Direction: executive capacity and Parliamentary oversight deepened together.'],'The early Charter phase retained Company commerce while tightening imperial direction.'),
('CHARTER ACT 1813',['MONOPOLY ENDS: INDIA TRADE','TEA + CHINA EXCEPTED','MISSION + EDUCATION OPENING'],['Ended Company monopoly in Indian trade; tea/China remained excepted.','Opened India to other British merchants and missionaries.','Marked Company shift from trader toward governing agency.'],'1813 weakened commercial exclusivity without yet ending Company rule.'),
('CHARTER ACT 1833',['ALL-INDIA GOVERNMENT','BENGAL GG -> GOVERNOR-GENERAL OF INDIA','COMPANY COMMERCIAL ROLE ENDS','LAW MEMBER'],['Centralised legislative power under Governor-General of India.','Company ceased commercial functions; remained administrative instrument.','Law Member/legislative machinery signalled uniform imperial governance.'],'1833 converted the Company from trader-ruler into a governing instrument.'),
('CHARTER ACT 1853',['LEGISLATIVE–EXECUTIVE SEPARATION','OPEN COMPETITIVE CIVIL SERVICE','NO FIXED RENEWAL'],['Separated legislative functions of Governor-General’s Council.','Opened civil-service competition in principle.','No fixed twenty-year renewal: Company tenure became provisional.'],'1853 made the Company constitutional machinery awaiting replacement.'),
('GOVERNMENT OF INDIA ACT 1858',['CROWN RULE','COMPANY ABOLISHED','SECRETARY OF STATE','VICEROY'],['Company rule ended after 1857; Crown assumed government.','Secretary of State in Council replaced Board/Court control machinery.','Governor-General became Viceroy: imperial executive now directly responsible to Crown.'],'1858 replaces Company governance with Crown responsibility, not representative government.'),
('COUNCILS ACTS 1861 + 1892',['1861: PORTFOLIOS + NOMINATION','1892: INDIRECT ELECTION ELEMENT','ASSOCIATION, NOT RESPONSIBILITY'],['1861 restored legislative councils and recognised portfolio administration.','1892 enlarged councils and introduced an indirect electoral principle.','Limit: executives remained unresponsible to elected Indians.'],'Councils widened consultation; they did not yet transfer executive responsibility.'),
('1909 + 1919',['1909: COMMUNAL ELECTORATES','1919: DYARCHY IN PROVINCES','CENTRE STILL RESPONSIBLE TO BRITAIN'],['1909 institutionalised separate communal electorates.','1919 split provincial subjects: transferred ministers versus reserved Governor control.','Responsible government remained partial and provincial, not central.'],'1909 changed representation; 1919 tested limited responsibility through dyarchy.'),
('GOVERNMENT OF INDIA ACT 1935',['FEDERAL SCHEME','3 LEGISLATIVE LISTS','PROVINCIAL AUTONOMY','GOVERNOR SAFEGUARDS'],['Proposed federation; federal part did not fully operate.','Federal, provincial and concurrent lists structured legislative power.','Provincial autonomy expanded, but Governors retained safeguards/discretion.'],'1935 supplied the institutional grammar later adapted by the Constitution.'),
('INDEPENDENCE ACT 1947',['SOVEREIGN DOMINIONS','PARAMOUNTCY LAPSED','CONSTITUENT ASSEMBLIES SOVEREIGN'],['Created India and Pakistan as independent Dominions.','Lapsed British paramountcy over princely states.','Constituent Assembly acquired sovereign law-making authority.'],'1947 ends imperial constitutional control and opens constitution-making sovereignty.'),
]
