d.rounded_rectangle((280,y,W-120,y+380),25,fill='#112c3b',outline='#99b0ba',width=4);d.text((320,y+30),'FINAL SYNTHESIS — THE CONSTITUTIONAL EVOLUTION',font=bold(42),fill='white');d.text((320,y+105),'COMPANY TRADE → PARLIAMENTARY CONTROL → DUAL CONTROL → CROWN RULE → ASSOCIATION → REPRESENTATION → PROVINCIAL RESPONSIBILITY → FEDERATION/AUTONOMY → SOVEREIGNTY',font=bold(27),fill='#57d7e8');d.text((320,y+185),'EXAM ROUTE: distinguish regulation from responsibility; commercial administration from political control; provincial autonomy from sovereign federalism.',font=reg(26),fill='#d5e8ee');im.save(OUT/'master.png',dpi=(300,300));r.poster_pdf(OUT/'master.png',OUT/'poster.pdf',im.size);st=[(i+1,510+i*510,510+(i+1)*510) for i in range(len(stages))];r.tile_pdf(OUT/'master.png',OUT/'tiled.pdf',im.size,st);r.render_previews(OUT/'tiled.pdf',OUT/'previews');spec={'topic':'polity-01','spine':'Company trade -> parliamentary control -> dual control -> Crown rule -> association -> representation -> provincial responsibility -> federation/autonomy -> sovereignty','stages':[{'title':a,'pills':b,'layout':'three-column constitutional timeline','must_show':c,'answer_band':e} for a,b,c,e in stages],'subordinate_enrichment':['comparative Acts/PYQ route after core']};(OUT/'bespoke-design-spec.json').write_text(json.dumps(spec,indent=2),encoding='utf8');h=hashlib.sha256((REF/'Carvaka_Continuous-At-a-Glance-Core-First_Poster_2026-08-22.pdf').read_bytes()).hexdigest();(OUT/'README.txt').write_text('Bespoke Cārvāka-standard Polity 01 companion\nReference SHA256 before/after: '+h+'\n',encoding='utf8');print(OUT)
